SELECT time, source_stream, source_row_id, pid, ppid, pname, process_name, command_line, object, childproc_name, access, raw_event_type, original_table, parent_process_name, parent_process_path, parent_command_line, process_guid, parent_process_guid, alert_name, alert_reason, alert_category, filemod_name, regmod_name, modload_name, netconn_domain, remote_ip, remote_port
FROM audit_logs
WHERE source_row_id = '996679';

SELECT time, source_stream, source_row_id, pid, ppid, pname, process_name, command_line, object, childproc_name, access, raw_event_type
FROM audit_logs
WHERE source_row_id = '996679'
  AND (
    COALESCE(time,'') || '|' || COALESCE(CAST(pid AS TEXT),'') || '|' || COALESCE(CAST(ppid AS TEXT),'') || '|' || COALESCE(pname,'') || '|' || COALESCE(process_name,'') || '|' || COALESCE(access,'') || '|' || COALESCE(object,'') || '|' || COALESCE(CAST(event_record_id AS TEXT),'') || '|' || COALESCE(CAST(event_id AS TEXT),'') || '|' || COALESCE(subject_user_name,'') || '|' || COALESCE(access_mask,'') || '|' || COALESCE(access_list,'') || '|' || COALESCE(source_stream,'') || '|' || COALESCE(source_object_type,'') || '|' || COALESCE(command_line,'') || '|' || COALESCE(hashes,'') || '|' || COALESCE(parent_process_name,'') || '|' || COALESCE(parent_process_path,'') || '|' || COALESCE(parent_command_line,'') || '|' || COALESCE(process_guid,'') || '|' || COALESCE(parent_process_guid,'') || '|' || COALESCE(alert_name,'') || '|' || COALESCE(alert_reason,'') || '|' || COALESCE(alert_category,'') || '|' || COALESCE(raw_event_type,'') || '|' || COALESCE(filemod_name,'') || '|' || COALESCE(regmod_name,'') || '|' || COALESCE(modload_name,'') || '|' || COALESCE(childproc_name,'') || '|' || COALESCE(netconn_domain,'') || '|' || COALESCE(remote_ip,'') || '|' || COALESCE(remote_port,'') || '|' || COALESCE(original_table,'') || '|' || COALESCE(source_row_id,'') || '|' || COALESCE(adapter_version,'')
